export function parse(text) {
  // simple enough for tool YAML configs (key: value layout)
  try {
    // try JSON first
    return JSON.parse(text);
  } catch (e) { /* fall through to naive indentation parser */ }
  const lines = text.split("\n");
  const root = {};
  const stack = [{ val: root, indent: -1, key: null }];
  let current = root;
  for (const raw of lines) {
    const line = raw.replace(/\s+#.*$/, "").replace(/^\s+/, "");
    if (!line.trim()) continue;
    const indent = raw.match(/^ */)[0].length;
    const sep = line.indexOf(":");
    if (sep < 0) continue;
    const key = line.slice(0, sep).trim();
    const valStr = line.slice(sep+1).trim();
    if (valStr === "") {
      current[key] = {};
      stack.push({ val: current, key, indent });
      current = current[key];
    } else {
      current[key] = value(valStr);
    }
  }
  return root;

  function value(s) {
    if (s === "true") return true; if (s === "false") return false;
    if (!isNaN(Number(s)) && s !== "") return Number(s);
    if (s.startsWith('"') && s.endsWith('"')) return s.slice(1,-1);
    if (s.startsWith('[') && s.endsWith(']')) return JSON.parse(s.replace(/'/g,'\"'));
    return s;
  }
}
export { parse as parseDocument, parse as parseAllDocuments };
export function stringify(obj) { return obj && typeof obj === "object" ? JSON.stringify(obj) : String(obj); }
